/**
 * Serves the holding page for every path, with 503.
 *
 * The status matters. A 200 tells crawlers "this is the page now" and the course's
 * real pages get dropped from the index; 503 with Retry-After says "temporarily
 * away, come back", which is what is actually true.
 *
 * The HTML is inlined rather than read through the assets binding. In advanced
 * mode (a _worker.js at the root) `env.ASSETS.fetch` returned an empty body here,
 * and a holding page that depends on a binding to render is a holding page with a
 * way to fail. Everything it needs — the logo, the styles — is in this file.
 *
 * The app itself is untouched: this is a separate upload to the same Pages project.
 * Restoring the course is `npm run pages:deploy` from the repository root.
 */
const PAGE = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Transplant Alchemy 101 &middot; Save7</title>
<meta name="robots" content="noindex">
<link rel="icon" href="data:image/svg+xml;base64," type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Anton&family=Inter:wght@400;600&display=swap" rel="stylesheet">
<style>
  :root {
    --ink: #111111;
    --cream: #f7f3ee;
    --pink: #ed0e69;
    --teal: #16b9b4;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; }
  body {
    background: var(--ink);
    color: var(--cream);
    font: 400 17px/1.6 Inter, system-ui, -apple-system, sans-serif;
    display: grid;
    place-items: center;
    padding: 32px 20px;
    /* A quiet wash of brand colour, so the page is not a flat black rectangle. */
    background-image:
      radial-gradient(120% 90% at 8% 0%, rgba(237, 14, 105, 0.20), transparent 60%),
      radial-gradient(90% 80% at 100% 100%, rgba(22, 185, 180, 0.16), transparent 58%);
    background-attachment: fixed;
  }
  main { width: 100%; max-width: 34rem; }
  .logo { width: 168px; height: auto; display: block; }
  .eyebrow {
    margin: 44px 0 0;
    font: 600 12px/1.4 Inter, sans-serif;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--teal);
  }
  h1 {
    margin: 14px 0 0;
    font: 400 clamp(2.6rem, 12vw, 4.25rem)/0.92 Anton, Impact, sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.01em;
  }
  h1 .rule { color: var(--pink); }
  p { margin: 22px 0 0; color: rgba(247, 243, 238, 0.78); }
  p.tight { margin-top: 12px; }
  .divider {
    margin: 34px 0 0;
    width: 64px;
    height: 3px;
    background: var(--pink);
    border: 0;
  }
  a { color: var(--cream); text-decoration: underline; text-underline-offset: 3px; }
  a:hover { color: var(--teal); }
  footer {
    margin: 44px 0 0;
    font-size: 14px;
    color: rgba(247, 243, 238, 0.45);
  }
  @media (prefers-reduced-motion: no-preference) {
    main { animation: rise 0.5s ease-out both; }
    @keyframes rise { from { opacity: 0; transform: translateY(8px); } }
  }
</style>
</head>
<body>
<main>
  <img class="logo" alt="Save7" src="data:image/png;base64,">
  <p class="eyebrow">Transplant Alchemy 101</p>
  <h1>Under<br>construction<span class="rule">.</span></h1>
  <hr class="divider">
  <p>
    Save7&rsquo;s organ donation and transplantation awareness course is being
    finished. It will be back here shortly.
  </p>
  <p class="tight">
    In the meantime, Save7 is at
    <a href="https://save7.org">save7.org</a>.
  </p>
  <footer>Save7 &middot; A South African organ donation awareness initiative</footer>
</main>
</body>
</html>
`;

export default {
  fetch() {
    return new Response(PAGE, {
      status: 503,
      headers: {
        "content-type": "text/html; charset=utf-8",
        // An hour is a guess, and a guess beats nothing: it stops crawlers
        // hammering and tells them not to treat this as permanent.
        "retry-after": "3600",
        "cache-control": "no-store",
        "x-robots-tag": "noindex",
      },
    });
  },
};
